INSERT INTO `hs_math_train_items` VALUES (1,'HS_MATH_P0_E2E_TEST_single','formal','single','HS_MATH_P0_E2E_TEST single 题干','{\"options\": [{\"id\": \"A\", \"text\": \"选项A-E2E\"}, {\"id\": \"B\", \"text\": \"选项B-E2E\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','HS_MATH_P0_E2E_TEST 解析含标准答案勿泄露','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,16,NULL,'disabled',1,'v1',1,2,2,2,'2026-10-24 09:30:41.935','2026-10-24 09:30:41.433','2026-10-24 10:39:14.916'),(2,'HS_MATH_P0_E2E_TEST_multi','formal','multi','HS_MATH_P0_E2E_TEST multi 题干','{\"options\": [{\"id\": \"A\", \"text\": \"A\"}, {\"id\": \"B\", \"text\": \"B\"}, {\"id\": \"C\", \"text\": \"C\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"C\"]}','HS_MATH_P0_E2E_TEST 解析含标准答案勿泄露','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,16,NULL,'disabled',1,'v1',1,2,2,2,'2026-10-24 09:30:42.208','2026-10-24 09:30:41.507','2026-10-24 10:39:14.916'),(3,'HS_MATH_P0_E2E_TEST_judge','formal','judge','HS_MATH_P0_E2E_TEST judge 题干',NULL,'{\"kind\": \"judge\", \"value\": true}','HS_MATH_P0_E2E_TEST 解析含标准答案勿泄露','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,16,NULL,'disabled',1,'v1',1,2,2,2,'2026-10-24 09:30:42.457','2026-10-24 09:30:41.605','2026-10-24 10:39:14.916'),(4,'HS_MATH_P0_E2E_TEST_numeric','formal','numeric','HS_MATH_P0_E2E_TEST numeric 题干',NULL,'{\"kind\": \"numeric\", \"value\": \"1.5\", \"toleranceAbs\": 0.01, \"toleranceRel\": 0}','HS_MATH_P0_E2E_TEST 解析含标准答案勿泄露','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,16,NULL,'disabled',1,'v1',1,2,2,2,'2026-10-24 09:30:42.573','2026-10-24 09:30:41.697','2026-10-24 10:39:14.916'),(5,'HS_MATH_P0_E2E_TEST_single2','formal','single','HS_MATH_P0_E2E_TEST single2 填充','{\"options\": [{\"id\": \"A\", \"text\": \"选项A-E2E\"}, {\"id\": \"B\", \"text\": \"选项B-E2E\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','HS_MATH_P0_E2E_TEST 解析含标准答案勿泄露','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,16,NULL,'disabled',1,'v1',1,2,2,2,'2026-10-24 09:30:42.636','2026-10-24 09:30:41.798','2026-10-24 10:39:14.916'),(26,'HSMA-RJA-CH01-0001','formal','single','下列对象中，能构成集合的是','{\"options\": [{\"id\": \"A\", \"text\": \"某班成绩很好的同学\"}, {\"id\": \"B\", \"text\": \"接近 $1$ 的实数\"}, {\"id\": \"C\", \"text\": \"方程 $x^{2}-1=0$ 的实数根\"}, {\"id\": \"D\", \"text\": \"个子较高的人\"}]}','{\"kind\": \"single\", \"optionId\": \"C\"}','集合的元素必须具有确定性。方程 $x^{2}-1=0$ 的实数根是 $-1$ 与 $1$，对象明确。A、B、D 中“很好”“接近”“较高”含义不唯一，不能构成集合。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,31,1,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.078','2026-10-24 17:00:31.078'),(27,'HSMA-RJA-CH01-0002','formal','single','设 $A=\\{1,2,3\\}$，则下列正确的是','{\"options\": [{\"id\": \"A\", \"text\": \"$1\\\\subset A$\"}, {\"id\": \"B\", \"text\": \"$1\\\\in A$\"}, {\"id\": \"C\", \"text\": \"$\\\\{1\\\\}\\\\in A$\"}, {\"id\": \"D\", \"text\": \"$\\\\{1,2\\\\}\\\\in A$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','元素与集合用 $\\in$；集合与集合用 $\\subseteq$ 或 $\\subset$。$1$ 是 $A$ 的元素，故 $1\\in A$。$\\{1\\}$ 是集合，应写作 $\\{1\\}\\subseteq A$，不能写成 $\\{1\\}\\in A$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,31,1,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.084','2026-10-24 17:00:31.084'),(28,'HSMA-RJA-CH01-0003','formal','single','用列举法表示集合 $\\{x\\in\\mathbb{Z}\\mid -2\\le x<2\\}$，正确的是（$\\mathbb{Z}$ 表示整数集）','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\{-2,-1,0,1,2\\\\}$\"}, {\"id\": \"B\", \"text\": \"$\\\\{-2,-1,0,1\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{-1,0,1\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\{-2,-1,0\\\\}$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','条件为 $-2\\le x<2$ 且 $x$ 为整数，故 $x=-2,-1,0,1$，写作 $\\{-2,-1,0,1\\}$。不含 $2$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,31,2,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.088','2026-10-24 17:00:31.088'),(29,'HSMA-RJA-CH01-0004','formal','single','下列用描述法表示集合正确的是','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\{x\\\\mid x^{2}=1\\\\}$（未指明数集时默认在实数范围内讨论）\"}, {\"id\": \"B\", \"text\": \"$\\\\{x\\\\mid x$ 是较大的正整数$\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{x\\\\mid x$ 接近 $0\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\{x\\\\mid x$ 是好看的图形$\\\\}$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','高中默认在实数集讨论时，$x^{2}=1$ 的解为 $\\pm 1$，属性确定。其余选项含模糊用语，不能作为集合的描述条件。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,31,2,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.093','2026-10-24 17:00:31.093'),(30,'HSMA-RJA-CH01-0005','formal','single','关于空集 $\\varnothing$，正确的是','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\varnothing$ 不含任何元素\"}, {\"id\": \"B\", \"text\": \"$\\\\varnothing=\\\\{0\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\varnothing=\\\\{\\\\varnothing\\\\}$\"}, {\"id\": \"D\", \"text\": \"$0\\\\in\\\\varnothing$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','空集是不含任何元素的集合。$\\{0\\}$ 含元素 $0$；$\\{\\varnothing\\}$ 含元素 $\\varnothing$，都不是空集。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,31,3,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.097','2026-10-24 17:00:31.097'),(31,'HSMA-RJA-CH01-0006','formal','single','设 $A=\\{a,b\\}$，且 $a\\ne b$。下列说法正确的是','{\"options\": [{\"id\": \"A\", \"text\": \"$A$ 有 $2$ 个元素\"}, {\"id\": \"B\", \"text\": \"若再写入 $a$，则 $A$ 有 $3$ 个元素\"}, {\"id\": \"C\", \"text\": \"集合中元素可以重复计数\"}, {\"id\": \"D\", \"text\": \"$\\\\{a,a,b\\\\}$ 与 $A$ 元素个数不同\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','集合元素具有互异性：$\\{a,a,b\\}=\\{a,b\\}$，仍是 $2$ 个元素。不能因书写重复而增加元素个数。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,31,1,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.102','2026-10-24 17:00:31.102'),(32,'HSMA-RJA-CH01-0007','formal','single','常用数集中，$\\mathbb{N}$、$\\mathbb{Z}$、$\\mathbb{Q}$、$\\mathbb{R}$ 分别表示自然数集、整数集、有理数集、实数集。下列正确的是（本题约定 $\\mathbb{N}$ 含 $0$）','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\mathbb{N}\\\\subseteq\\\\mathbb{Z}\\\\subseteq\\\\mathbb{Q}\\\\subseteq\\\\mathbb{R}$\"}, {\"id\": \"B\", \"text\": \"$\\\\mathbb{R}\\\\subseteq\\\\mathbb{Q}$\"}, {\"id\": \"C\", \"text\": \"$\\\\sqrt{2}\\\\in\\\\mathbb{Q}$\"}, {\"id\": \"D\", \"text\": \"$-3\\\\in\\\\mathbb{N}$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','在含 $0$ 的约定下，自然数都是整数，整数都是有理数，有理数都是实数，故包含链成立。$\\sqrt{2}$ 不是有理数；$-3$ 不是自然数。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,31,2,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.105','2026-10-24 17:00:31.105'),(33,'HSMA-RJA-CH01-0008','formal','single','设集合 $A=\\{x\\mid x=2k+1,\\,k\\in\\mathbb{Z}\\}$（奇数集）。则 $-5\\in A$ 的判断是','{\"options\": [{\"id\": \"A\", \"text\": \"正确\"}, {\"id\": \"B\", \"text\": \"错误\"}, {\"id\": \"C\", \"text\": \"无法判断\"}, {\"id\": \"D\", \"text\": \"仅当 $k>0$ 时正确\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','取 $k=-3$，则 $2k+1=-5$，故 $-5\\in A$。奇数集包含负奇数。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,31,1,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.110','2026-10-24 17:00:31.110'),(34,'HSMA-RJA-CH01-0009','formal','multi','下列可以作为集合的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"小于 $10$ 的正整数\"}, {\"id\": \"B\", \"text\": \"方程 $x^{2}+1=0$ 的实数根\"}, {\"id\": \"C\", \"text\": \"著名的数学家\"}, {\"id\": \"D\", \"text\": \"平面内到定点距离等于定长的点\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"D\"]}','A：正整数 $1$ 到 $9$，确定。B：实数范围内无解，为空集，仍是集合。D：圆上的点，几何属性确定。C：“著名”不唯一，不能构成集合。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,31,1,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.114','2026-10-24 17:00:31.114'),(35,'HSMA-RJA-CH01-0010','formal','multi','关于集合表示法，正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"列举法适合元素不多的集合\"}, {\"id\": \"B\", \"text\": \"描述法用元素的共同属性刻画集合\"}, {\"id\": \"C\", \"text\": \"无限集一定不能用列举法表示\"}, {\"id\": \"D\", \"text\": \"$\\\\{1,2,3\\\\}$ 是列举法\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"D\"]}','列举法与描述法是基本表示法。无限集有时可写省略号列举（如正偶数），故 C 过绝对。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,31,2,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.119','2026-10-24 17:00:31.119'),(36,'HSMA-RJA-CH01-0011','formal','multi','设 $A=\\{\\varnothing\\}$。下列正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\varnothing\\\\in A$\"}, {\"id\": \"B\", \"text\": \"$\\\\varnothing\\\\subseteq A$\"}, {\"id\": \"C\", \"text\": \"$A=\\\\varnothing$\"}, {\"id\": \"D\", \"text\": \"$A$ 含有 $1$ 个元素\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"D\"]}','$A=\\{\\varnothing\\}$ 的唯一元素是空集，故 $\\varnothing\\in A$，且 $|A|=1$。空集是任何集合的子集，故 $\\varnothing\\subseteq A$。但 $A$ 不是空集。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,31,3,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.122','2026-10-24 17:00:31.122'),(37,'HSMA-RJA-CH01-0012','formal','judge','集合 $\\{1,2,3\\}$ 与集合 $\\{3,2,1\\}$ 是同一个集合。',NULL,'{\"kind\": \"judge\", \"value\": true}','集合元素具有无序性：只要元素完全相同，书写顺序不同仍表示同一个集合，因此两者相等。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,31,1,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.126','2026-10-24 17:00:31.126'),(38,'HSMA-RJA-CH01-0013','formal','judge','空集是任何一个集合的元素。',NULL,'{\"kind\": \"judge\", \"value\": false}','空集是任何一个集合的子集（$\\varnothing\\subseteq A$），但不一定是元素。例如 $1\\notin\\{1,2\\}$ 同理，$\\varnothing\\notin\\{1,2\\}$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,31,3,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.130','2026-10-24 17:00:31.130'),(39,'HSMA-RJA-CH01-0014','formal','judge','用描述法表示集合时，必须写清代表元素所属的范围（或约定默认范围）。',NULL,'{\"kind\": \"judge\", \"value\": true}','描述法依赖属性与论域；论域不清会导致集合不明确。教材书写常写 $x\\in\\mathbb{R}$ 等。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,31,2,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.133','2026-10-24 17:00:31.133'),(40,'HSMA-RJA-CH01-0015','formal','numeric','集合 $\\{2,4,6,8\\}$ 的元素个数是',NULL,'{\"kind\": \"numeric\", \"value\": \"4\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','该集合含 $2,4,6,8$ 四个互不相同的元素，由元素互异性知其元素个数为 $4$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,31,1,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.137','2026-10-24 17:00:31.137'),(41,'HSMA-RJA-CH01-0016','formal','numeric','集合 $\\{x\\in\\mathbb{Z}\\mid 0<x\\le 5\\}$ 的元素个数是',NULL,'{\"kind\": \"numeric\", \"value\": \"5\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','正整数（本题由 $0<x$ 且整数得到）$1,2,3,4,5$，共 $5$ 个。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,31,2,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.141','2026-10-24 17:00:31.141'),(42,'HSMA-RJA-CH01-0017','formal','single','若 $A\\subseteq B$，则下列一定正确的是','{\"options\": [{\"id\": \"A\", \"text\": \"$A$ 的任意元素都属于 $B$\"}, {\"id\": \"B\", \"text\": \"$A$ 一定是 $B$ 的真子集\"}, {\"id\": \"C\", \"text\": \"$B\\\\subseteq A$\"}, {\"id\": \"D\", \"text\": \"$A$ 与 $B$ 元素个数一定相等\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','$A\\subseteq B$ 的定义是：$A$ 中任一元素都属于 $B$。真子集还需 $A\\ne B$，故不一定是真子集。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.145','2026-10-24 17:00:31.145'),(43,'HSMA-RJA-CH01-0018','formal','single','设 $A=\\{1,2\\}$，$B=\\{1,2,3\\}$，则','{\"options\": [{\"id\": \"A\", \"text\": \"$A\\\\subsetneq B$（$A$ 是 $B$ 的真子集）\"}, {\"id\": \"B\", \"text\": \"$B\\\\subseteq A$\"}, {\"id\": \"C\", \"text\": \"$A=B$\"}, {\"id\": \"D\", \"text\": \"$3\\\\in A$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','$A$ 的元素都属于 $B$，且 $3\\in B$ 但 $3\\notin A$，故 $A$ 是 $B$ 的真子集。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.148','2026-10-24 17:00:31.148'),(44,'HSMA-RJA-CH01-0019','formal','single','集合 $A=B$ 的充要条件是','{\"options\": [{\"id\": \"A\", \"text\": \"$A\\\\subseteq B$ 且 $B\\\\subseteq A$\"}, {\"id\": \"B\", \"text\": \"仅 $A\\\\subseteq B$\"}, {\"id\": \"C\", \"text\": \"仅 $A$ 与 $B$ 元素个数相等\"}, {\"id\": \"D\", \"text\": \"$A\\\\cap B=\\\\varnothing$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','两集合相等的充要条件是互相包含。仅有 $A\\subseteq B$ 不够；元素个数相等也不能保证元素相同。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,32,5,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.151','2026-10-24 17:00:31.151'),(45,'HSMA-RJA-CH01-0020','formal','single','下列说法正确的是','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\varnothing\\\\subseteq\\\\{1\\\\}$\"}, {\"id\": \"B\", \"text\": \"$\\\\varnothing\\\\in\\\\{1\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{\\\\varnothing\\\\}=\\\\varnothing$\"}, {\"id\": \"D\", \"text\": \"$1\\\\subseteq\\\\{1\\\\}$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','空集是任何集合的子集。$\\varnothing$ 不是 $\\{1\\}$ 的元素；$\\{\\varnothing\\}$ 非空；$1$ 是元素不是集合，不能写 $1\\subseteq\\{1\\}$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.155','2026-10-24 17:00:31.155'),(46,'HSMA-RJA-CH01-0021','formal','single','设集合 $A$ 含有 $3$ 个元素，则 $A$ 的子集个数是','{\"options\": [{\"id\": \"A\", \"text\": \"$3$\"}, {\"id\": \"B\", \"text\": \"$6$\"}, {\"id\": \"C\", \"text\": \"$8$\"}, {\"id\": \"D\", \"text\": \"$9$\"}]}','{\"kind\": \"single\", \"optionId\": \"C\"}','含 $n$ 个元素的集合有 $2^{n}$ 个子集。$n=3$ 时为 $2^{3}=8$（含空集与自身）。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.159','2026-10-24 17:00:31.159'),(47,'HSMA-RJA-CH01-0022','formal','single','设集合 $A$ 含有 $3$ 个元素，则 $A$ 的真子集个数是','{\"options\": [{\"id\": \"A\", \"text\": \"$7$\"}, {\"id\": \"B\", \"text\": \"$8$\"}, {\"id\": \"C\", \"text\": \"$6$\"}, {\"id\": \"D\", \"text\": \"$3$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','真子集是不等于自身的子集，个数为 $2^{n}-1$。$n=3$ 时为 $7$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.162','2026-10-24 17:00:31.162'),(48,'HSMA-RJA-CH01-0023','formal','single','若 $\\{1,2\\}\\subseteq A\\subseteq\\{1,2,3\\}$，则集合 $A$ 的可能情况种数是','{\"options\": [{\"id\": \"A\", \"text\": \"$1$\"}, {\"id\": \"B\", \"text\": \"$2$\"}, {\"id\": \"C\", \"text\": \"$3$\"}, {\"id\": \"D\", \"text\": \"$4$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','$A$ 必须含 $1,2$，对 $3$ 可取可不取，故 $A=\\{1,2\\}$ 或 $\\{1,2,3\\}$，共 $2$ 种。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.165','2026-10-24 17:00:31.165'),(49,'HSMA-RJA-CH01-0024','formal','single','设 $A=\\{x\\mid x^{2}-3x+2=0\\}$，$B=\\{1,2\\}$，则','{\"options\": [{\"id\": \"A\", \"text\": \"$A=B$\"}, {\"id\": \"B\", \"text\": \"$A\\\\subsetneq B$\"}, {\"id\": \"C\", \"text\": \"$B\\\\subsetneq A$\"}, {\"id\": \"D\", \"text\": \"$A\\\\cap B=\\\\varnothing$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','$x^{2}-3x+2=(x-1)(x-2)=0$，得 $x=1$ 或 $2$，故 $A=\\{1,2\\}=B$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,32,5,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.169','2026-10-24 17:00:31.169'),(50,'HSMA-RJA-CH01-0025','formal','multi','设 $A=\\{a\\}$。下列正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\varnothing\\\\subseteq A$\"}, {\"id\": \"B\", \"text\": \"$A\\\\subseteq A$\"}, {\"id\": \"C\", \"text\": \"$\\\\{a\\\\}\\\\subseteq A$\"}, {\"id\": \"D\", \"text\": \"$a\\\\subseteq A$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','任何集合是自身的子集；空集是子集；$\\{a\\}=A$ 故也成立。$a$ 是元素，不能写 $a\\subseteq A$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.173','2026-10-24 17:00:31.173'),(51,'HSMA-RJA-CH01-0026','formal','multi','下列关系正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\{1\\\\}\\\\subseteq\\\\{1,2\\\\}$\"}, {\"id\": \"B\", \"text\": \"$\\\\{1,2\\\\}=\\\\{2,1\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{1\\\\}\\\\in\\\\{1,2\\\\}$\"}, {\"id\": \"D\", \"text\": \"$1\\\\in\\\\{1,2\\\\}$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"D\"]}','子集与相等成立；$1$ 属于该集合。但 $\\{1\\}$ 不是 $\\{1,2\\}$ 的元素，C 错误。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,32,5,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.450','2026-10-24 17:00:31.450'),(52,'HSMA-RJA-CH01-0027','formal','multi','设 $A=\\{1,2,3\\}$。下列是 $A$ 的真子集的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\varnothing$\"}, {\"id\": \"B\", \"text\": \"$\\\\{1,2\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{1,2,3\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\{2\\\\}$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"D\"]}','真子集不能等于自身，故排除 C。空集与真子集 $\\{1,2\\}$、$\\{2\\}$ 均正确。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.454','2026-10-24 17:00:31.454'),(53,'HSMA-RJA-CH01-0028','formal','judge','若 $A\\subseteq B$ 且 $B\\subseteq A$，则 $A=B$。',NULL,'{\"kind\": \"judge\", \"value\": true}','互相包含正是集合相等的定义：一边包含保证元素关系，两边同时成立则两集合相同。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,32,5,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.456','2026-10-24 17:00:31.456'),(54,'HSMA-RJA-CH01-0029','formal','judge','空集没有真子集。',NULL,'{\"kind\": \"judge\", \"value\": true}','空集的子集只有它自身，真子集个数为 $2^{0}-1=0$，因此空集没有真子集。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.459','2026-10-24 17:00:31.459'),(55,'HSMA-RJA-CH01-0030','formal','numeric','集合 $\\{a,b\\}$（$a\\ne b$）的子集个数是',NULL,'{\"kind\": \"numeric\", \"value\": \"4\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','元素个数 $n=2$，子集个数为 $2^{2}=4$，分别是 $\\varnothing,\\{a\\},\\{b\\},\\{a,b\\}$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.462','2026-10-24 17:00:31.462'),(56,'HSMA-RJA-CH01-0031','formal','numeric','集合 $\\{1,2,3,4\\}$ 的真子集个数是',NULL,'{\"kind\": \"numeric\", \"value\": \"15\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','元素个数 $n=4$，真子集个数为 $2^{4}-1=15$（去掉集合自身）。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.465','2026-10-24 17:00:31.465'),(57,'HSMA-RJA-CH01-0032','formal','numeric','若集合 $A$ 的子集共有 $16$ 个，则 $A$ 的元素个数是',NULL,'{\"kind\": \"numeric\", \"value\": \"4\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','由子集个数公式 $2^{n}=16$，解得元素个数 $n=4$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,32,4,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.468','2026-10-24 17:00:31.468'),(58,'HSMA-RJA-CH01-0033','formal','single','设 $A=\\{1,2,3\\}$，$B=\\{2,3,4\\}$，则 $A\\cup B=$','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\{2,3\\\\}$\"}, {\"id\": \"B\", \"text\": \"$\\\\{1,2,3,4\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{1,4\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\varnothing$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','并集由属于 $A$ 或属于 $B$ 的全部元素组成，枚举得 $\\{1,2,3,4\\}$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,6,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.471','2026-10-24 17:00:31.471'),(59,'HSMA-RJA-CH01-0034','formal','single','设 $A=\\{1,2,3\\}$，$B=\\{2,3,4\\}$，则 $A\\cap B=$','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\{1,2,3,4\\\\}$\"}, {\"id\": \"B\", \"text\": \"$\\\\{2,3\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{1,4\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\{1,2,3\\\\}$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','交集由同时属于 $A$ 与 $B$ 的元素组成，公共元素为 $2,3$，故为 $\\{2,3\\}$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,7,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.474','2026-10-24 17:00:31.474'),(60,'HSMA-RJA-CH01-0035','formal','single','设全集 $U=\\{1,2,3,4,5\\}$，$A=\\{1,2,3\\}$，则 $\\complement_{U}A=$','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\{1,2,3\\\\}$\"}, {\"id\": \"B\", \"text\": \"$\\\\{4,5\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{3,4,5\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\varnothing$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','在给定全集 $U$ 下，补集是 $U$ 中不属于 $A$ 的元素，因此为 $\\{4,5\\}$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,8,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.477','2026-10-24 17:00:31.477'),(61,'HSMA-RJA-CH01-0036','formal','single','设 $A=\\{x\\mid x>1\\}$，$B=\\{x\\mid x\\le 3\\}$（$x\\in\\mathbb{R}$），则 $A\\cap B=$','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\{x\\\\mid 1<x\\\\le 3\\\\}$\"}, {\"id\": \"B\", \"text\": \"$\\\\{x\\\\mid x>1\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{x\\\\mid x\\\\le 3\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\{x\\\\mid x>3\\\\}$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','交集需同时满足 $x>1$ 与 $x\\le 3$，合取后得到 $1<x\\le 3$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,7,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.480','2026-10-24 17:00:31.480'),(62,'HSMA-RJA-CH01-0037','formal','single','设 $A=\\{x\\mid x<2\\}$，$B=\\{x\\mid x\\ge 0\\}$（$x\\in\\mathbb{R}$），则 $A\\cup B=$','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\mathbb{R}$\"}, {\"id\": \"B\", \"text\": \"$\\\\{x\\\\mid 0\\\\le x<2\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{x\\\\mid x<0\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\varnothing$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','小于 $2$ 的实数与不小于 $0$ 的实数并起来覆盖全体实数，故为 $\\mathbb{R}$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,6,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.483','2026-10-24 17:00:31.483'),(63,'HSMA-RJA-CH01-0038','formal','single','设全集 $U=\\mathbb{R}$，$A=\\{x\\mid x\\le 1\\}$，则 $\\complement_{U}A=$','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\{x\\\\mid x>1\\\\}$\"}, {\"id\": \"B\", \"text\": \"$\\\\{x\\\\mid x\\\\ge 1\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{x\\\\mid x<1\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\{x\\\\mid x\\\\le 1\\\\}$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','补集为不满足 $x\\le 1$ 的实数，即 $x>1$。注意端点：$1\\in A$，故 $1$ 不在补集中。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,8,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.487','2026-10-24 17:00:31.487'),(64,'HSMA-RJA-CH01-0039','formal','single','设 $A\\cap B=A$，则一定有','{\"options\": [{\"id\": \"A\", \"text\": \"$A\\\\subseteq B$\"}, {\"id\": \"B\", \"text\": \"$B\\\\subseteq A$\"}, {\"id\": \"C\", \"text\": \"$A=B$\"}, {\"id\": \"D\", \"text\": \"$A\\\\cup B=A$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','$A\\cap B=A$ 等价于 $A$ 的元素都属于 $B$，即 $A\\subseteq B$。由该式不能推出 $A=B$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,7,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.491','2026-10-24 17:00:31.491'),(65,'HSMA-RJA-CH01-0040','formal','single','设 $A\\cup B=A$，则一定有','{\"options\": [{\"id\": \"A\", \"text\": \"$B\\\\subseteq A$\"}, {\"id\": \"B\", \"text\": \"$A\\\\subseteq B$\"}, {\"id\": \"C\", \"text\": \"$A\\\\cap B=\\\\varnothing$\"}, {\"id\": \"D\", \"text\": \"$A=B$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','$A\\cup B=A$ 等价于 $B$ 的元素都属于 $A$，即 $B\\subseteq A$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,6,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.496','2026-10-24 17:00:31.496'),(66,'HSMA-RJA-CH01-0041','formal','single','设全集 $U=\\{1,2,3,4,5,6\\}$，$A=\\{1,3,5\\}$，$B=\\{1,2,3\\}$，则 $\\complement_{U}(A\\cup B)=$','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\{4,6\\\\}$\"}, {\"id\": \"B\", \"text\": \"$\\\\{2,4,6\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{4,5,6\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\{6\\\\}$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','$A\\cup B=\\{1,2,3,5\\}$，在 $U$ 中的补集为 $\\{4,6\\}$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,33,9,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.499','2026-10-24 17:00:31.499'),(67,'HSMA-RJA-CH01-0042','formal','single','设全集 $U=\\{a,b,c,d\\}$，$A=\\{a,b\\}$，$B=\\{b,c\\}$，则 $(\\complement_{U}A)\\cap B=$','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\{c\\\\}$\"}, {\"id\": \"B\", \"text\": \"$\\\\{b,c\\\\}$\"}, {\"id\": \"C\", \"text\": \"$\\\\{a\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\varnothing$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','$\\complement_{U}A=\\{c,d\\}$，与 $B=\\{b,c\\}$ 交得 $\\{c\\}$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,33,9,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.606','2026-10-24 17:00:31.606'),(68,'HSMA-RJA-CH01-0043','formal','multi','设 $A=\\{1,2\\}$，$B=\\{2,3\\}$。正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$2\\\\in A\\\\cup B$\"}, {\"id\": \"B\", \"text\": \"$2\\\\in A\\\\cap B$\"}, {\"id\": \"C\", \"text\": \"$1\\\\in A\\\\cap B$\"}, {\"id\": \"D\", \"text\": \"$3\\\\in A\\\\cup B$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"D\"]}','$A\\cup B=\\{1,2,3\\}$，$A\\cap B=\\{2\\}$。故 $1$ 不在交集中。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,6,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.611','2026-10-24 17:00:31.611'),(69,'HSMA-RJA-CH01-0044','formal','multi','设全集 $U=\\{1,2,3,4\\}$，$A=\\{1,2\\}$。正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$3\\\\in\\\\complement_{U}A$\"}, {\"id\": \"B\", \"text\": \"$1\\\\notin\\\\complement_{U}A$\"}, {\"id\": \"C\", \"text\": \"$\\\\complement_{U}A=\\\\{3,4\\\\}$\"}, {\"id\": \"D\", \"text\": \"$\\\\complement_{U}A=\\\\{2,3,4\\\\}$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','$\\complement_{U}A=\\{3,4\\}$，$1\\in A$ 故不属于补集。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,33,8,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.614','2026-10-24 17:00:31.614'),(70,'HSMA-RJA-CH01-0045','formal','multi','下列运算恒成立的是（多选；对任意集合 $A,B$）','{\"options\": [{\"id\": \"A\", \"text\": \"$A\\\\cap B=B\\\\cap A$\"}, {\"id\": \"B\", \"text\": \"$A\\\\cup B=B\\\\cup A$\"}, {\"id\": \"C\", \"text\": \"$A\\\\cap\\\\varnothing=\\\\varnothing$\"}, {\"id\": \"D\", \"text\": \"$A\\\\cup\\\\varnothing=\\\\varnothing$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','交、并满足交换律；任意集合与空集的交仍为空集。并上空集应得到原集合 $A$，故 D 错误。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,7,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.617','2026-10-24 17:00:31.617'),(71,'HSMA-RJA-CH01-0046','formal','multi','设 $A=\\{1,2,3,4\\}$，$B=\\{3,4,5\\}$。正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$A\\\\cup B=\\\\{1,2,3,4,5\\\\}$\"}, {\"id\": \"B\", \"text\": \"$A\\\\cap B=\\\\{3,4\\\\}$\"}, {\"id\": \"C\", \"text\": \"$(A\\\\cup B)\\\\cap A=A$\"}, {\"id\": \"D\", \"text\": \"$A\\\\cap B=A$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','并、交直接计算得 A、B。$(A\\cup B)\\cap A=A$ 恒成立。$A\\cap B\\ne A$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,33,9,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.622','2026-10-24 17:00:31.622'),(72,'HSMA-RJA-CH01-0047','formal','judge','对任意集合 $A$，都有 $A\\cup A=A$ 且 $A\\cap A=A$。',NULL,'{\"kind\": \"judge\", \"value\": true}','并、交满足幂等律：集合与自身取并或取交，结果仍是原来的集合 $A$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,6,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.626','2026-10-24 17:00:31.626'),(73,'HSMA-RJA-CH01-0048','formal','judge','若全集为 $U$，则 $\\complement_{U}(\\complement_{U}A)=A$。',NULL,'{\"kind\": \"judge\", \"value\": true}','在同一全集下，补集运算具有对合性：对补集再取补，回到原集合 $A$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,8,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.629','2026-10-24 17:00:31.629'),(74,'HSMA-RJA-CH01-0049','formal','numeric','设 $A=\\{1,2,3\\}$，$B=\\{3,4\\}$，则 $A\\cup B$ 的元素个数是',NULL,'{\"kind\": \"numeric\", \"value\": \"4\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','先求并集 $A\\cup B=\\{1,2,3,4\\}$，其中互异元素共 $4$ 个。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,6,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.632','2026-10-24 17:00:31.632'),(75,'HSMA-RJA-CH01-0050','formal','numeric','设 $A=\\{1,2,3,4\\}$，$B=\\{2,4,6\\}$，则 $A\\cap B$ 的元素个数是',NULL,'{\"kind\": \"numeric\", \"value\": \"2\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','先求交集 $A\\cap B=\\{2,4\\}$，公共元素共 $2$ 个。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,7,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.635','2026-10-24 17:00:31.635'),(76,'HSMA-RJA-CH01-0051','formal','numeric','设全集 $U=\\{1,2,3,4,5,6,7,8\\}$，$A=\\{2,4,6,8\\}$，则 $\\complement_{U}A$ 的元素个数是',NULL,'{\"kind\": \"numeric\", \"value\": \"4\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','$U$ 中去掉 $A$ 的偶数后剩奇数 $\\{1,3,5,7\\}$，元素个数为 $4$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,33,8,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.638','2026-10-24 17:00:31.638'),(77,'HSMA-RJA-CH01-0052','formal','numeric','设 $A=\\{1,2,3,4,5\\}$，$B=\\{4,5,6,7\\}$，则属于 $A\\cup B$ 但不属于 $A\\cap B$ 的元素个数是',NULL,'{\"kind\": \"numeric\", \"value\": \"5\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','$A\\cup B=\\{1,2,3,4,5,6,7\\}$（$7$ 个），$A\\cap B=\\{4,5\\}$（$2$ 个），对称差元素个数为 $7-2=5$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,33,9,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.640','2026-10-24 17:00:31.640'),(78,'HSMA-RJA-CH01-0053','formal','single','已知 $p\\Rightarrow q$。就“充分条件”而言，正确的是','{\"options\": [{\"id\": \"A\", \"text\": \"$p$ 是 $q$ 的充分条件\"}, {\"id\": \"B\", \"text\": \"$p$ 是 $q$ 的必要条件\"}, {\"id\": \"C\", \"text\": \"$q$ 是 $p$ 的充分条件\"}, {\"id\": \"D\", \"text\": \"$p$ 与 $q$ 互为充要条件\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','由定义：若 $p\\Rightarrow q$，则称 $p$ 是 $q$ 的充分条件；同时 $q$ 是 $p$ 的必要条件，但本题问充分条件对应项。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,34,10,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.644','2026-10-24 17:00:31.644'),(79,'HSMA-RJA-CH01-0054','formal','single','已知 $p\\Rightarrow q$。就“必要条件”而言，正确的是','{\"options\": [{\"id\": \"A\", \"text\": \"$q$ 是 $p$ 的必要条件\"}, {\"id\": \"B\", \"text\": \"$q$ 是 $p$ 的充分条件\"}, {\"id\": \"C\", \"text\": \"$p$ 是 $q$ 的必要条件\"}, {\"id\": \"D\", \"text\": \"$p\\\\Leftrightarrow q$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','由 $p\\Rightarrow q$ 的定义可知：$q$ 是 $p$ 成立的必要条件，不能把充分与必要的方向弄反。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,34,11,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.647','2026-10-24 17:00:31.647'),(80,'HSMA-RJA-CH01-0055','formal','single','“$x=1$”是“$x^{2}=1$”的','{\"options\": [{\"id\": \"A\", \"text\": \"充分不必要条件\"}, {\"id\": \"B\", \"text\": \"必要不充分条件\"}, {\"id\": \"C\", \"text\": \"充要条件\"}, {\"id\": \"D\", \"text\": \"既不充分也不必要条件\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','若 $x=1$，则 $x^{2}=1$，充分。但 $x^{2}=1$ 时还可能 $x=-1$，故不必要。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,34,10,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.650','2026-10-24 17:00:31.650'),(81,'HSMA-RJA-CH01-0056','formal','single','“$x>2$”是“$x>1$”的（$x\\in\\mathbb{R}$）','{\"options\": [{\"id\": \"A\", \"text\": \"充分不必要条件\"}, {\"id\": \"B\", \"text\": \"必要不充分条件\"}, {\"id\": \"C\", \"text\": \"充要条件\"}, {\"id\": \"D\", \"text\": \"既不充分也不必要条件\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','由 $x>2$ 可推出 $x>1$，充分。但 $x=1.5$ 满足 $x>1$ 却不满足 $x>2$，故不必要。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,34,10,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.654','2026-10-24 17:00:31.654'),(82,'HSMA-RJA-CH01-0057','formal','single','“$x>1$”是“$x>2$”的（$x\\in\\mathbb{R}$）','{\"options\": [{\"id\": \"A\", \"text\": \"必要不充分条件\"}, {\"id\": \"B\", \"text\": \"充分不必要条件\"}, {\"id\": \"C\", \"text\": \"充要条件\"}, {\"id\": \"D\", \"text\": \"既不充分也不必要条件\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','若 $x>2$ 则必有 $x>1$，故“$x>1$”是必要的；但 $x>1$ 推不出 $x>2$，故不充分。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,34,11,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.657','2026-10-24 17:00:31.657'),(83,'HSMA-RJA-CH01-0058','formal','single','“四边形是正方形”是“四边形是矩形”的','{\"options\": [{\"id\": \"A\", \"text\": \"充分不必要条件\"}, {\"id\": \"B\", \"text\": \"必要不充分条件\"}, {\"id\": \"C\", \"text\": \"充要条件\"}, {\"id\": \"D\", \"text\": \"既不充分也不必要条件\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','正方形一定是矩形，故充分；矩形未必是正方形，故不必要。因此是充分不必要条件。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,34,10,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.660','2026-10-24 17:00:31.660'),(84,'HSMA-RJA-CH01-0059','formal','single','设 $x\\in\\mathbb{R}$。“$x^{2}=0$”是“$x=0$”的','{\"options\": [{\"id\": \"A\", \"text\": \"充要条件\"}, {\"id\": \"B\", \"text\": \"充分不必要条件\"}, {\"id\": \"C\", \"text\": \"必要不充分条件\"}, {\"id\": \"D\", \"text\": \"既不充分也不必要条件\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','在实数范围内，$x^{2}=0\\Leftrightarrow x=0$，互为充要条件。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,34,12,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.663','2026-10-24 17:00:31.663'),(85,'HSMA-RJA-CH01-0060','formal','single','“$a>0$ 且 $b>0$”是“$ab>0$”的（$a,b\\in\\mathbb{R}$）','{\"options\": [{\"id\": \"A\", \"text\": \"充分不必要条件\"}, {\"id\": \"B\", \"text\": \"必要不充分条件\"}, {\"id\": \"C\", \"text\": \"充要条件\"}, {\"id\": \"D\", \"text\": \"既不充分也不必要条件\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','两正数乘积为正，充分。但 $a=-1,b=-2$ 时 $ab>0$ 却不满足同为正，故不必要。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,34,10,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.666','2026-10-24 17:00:31.666'),(86,'HSMA-RJA-CH01-0061','formal','multi','下列说法正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"若 $p\\\\Rightarrow q$，则 $p$ 是 $q$ 的充分条件\"}, {\"id\": \"B\", \"text\": \"若 $p\\\\Rightarrow q$，则 $q$ 是 $p$ 的必要条件\"}, {\"id\": \"C\", \"text\": \"若 $p\\\\Leftrightarrow q$，则 $p$ 是 $q$ 的充要条件\"}, {\"id\": \"D\", \"text\": \"充分条件一定是必要条件\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','A、B、C 均符合充分、必要、充要的定义。充分条件不必同时是必要条件，故 D 错误。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,34,12,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.671','2026-10-24 17:00:31.671'),(87,'HSMA-RJA-CH01-0062','formal','multi','设 $x\\in\\mathbb{R}$。下列中，“$x>0$”是“$x\\ge 0$”的（多选表述正确项）','{\"options\": [{\"id\": \"A\", \"text\": \"充分条件\"}, {\"id\": \"B\", \"text\": \"必要条件\"}, {\"id\": \"C\", \"text\": \"充分不必要条件\"}, {\"id\": \"D\", \"text\": \"充要条件\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"C\"]}','$x>0\\Rightarrow x\\ge 0$，故充分；但 $x=0$ 使后者真前者假，故不必要。因此也是充分不必要。B、D 错误。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,34,10,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.676','2026-10-24 17:00:31.676'),(88,'HSMA-RJA-CH01-0063','formal','multi','下列各组中，$p$ 是 $q$ 的必要条件的是（多选；设 $x\\in\\mathbb{R}$）','{\"options\": [{\"id\": \"A\", \"text\": \"$p:x>1$；$q:x>2$\"}, {\"id\": \"B\", \"text\": \"$p:x=1$；$q:x^{2}=1$\"}, {\"id\": \"C\", \"text\": \"$p:x\\\\ge 2$；$q:x>2$\"}, {\"id\": \"D\", \"text\": \"$p:x^{2}\\\\ge 0$；$q:x=1$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"C\", \"D\"]}','若 $q\\Rightarrow p$，则 $p$ 是 $q$ 的必要条件。A：$x>2\\Rightarrow x>1$。C：$x>2\\Rightarrow x\\ge 2$。D：$x=1\\Rightarrow x^{2}\\ge 0$。B：$x^{2}=1$ 推不出 $x=1$，故不是必要条件。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,34,11,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.679','2026-10-24 17:00:31.679'),(89,'HSMA-RJA-CH01-0064','formal','multi','设 $x\\in\\mathbb{R}$。下列中 $p$ 是 $q$ 的充要条件的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$p:x=2$；$q:|x|=2$\"}, {\"id\": \"B\", \"text\": \"$p:x-1=0$；$q:x=1$\"}, {\"id\": \"C\", \"text\": \"$p:x^{2}=4$；$q:|x|=2$\"}, {\"id\": \"D\", \"text\": \"$p:x>1$；$q:x\\\\ge 1$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"B\", \"C\"]}','B：显然等价。C：在实数内 $x^{2}=4\\Leftrightarrow |x|=2$。A：$|x|=2$ 含 $x=-2$，不等价。D：一方更强，非充要。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,34,12,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.682','2026-10-24 17:00:31.682'),(90,'HSMA-RJA-CH01-0065','formal','judge','若 $p$ 是 $q$ 的充分条件，则 $q$ 一定是 $p$ 的必要条件。',NULL,'{\"kind\": \"judge\", \"value\": true}','“$p$ 是 $q$ 的充分条件”即 $p\\Rightarrow q$，这同时意味着“$q$ 是 $p$ 的必要条件”。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,34,11,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.685','2026-10-24 17:00:31.685'),(91,'HSMA-RJA-CH01-0066','formal','judge','“$a=b$”是“$a^{2}=b^{2}$”的充要条件（$a,b\\in\\mathbb{R}$）。',NULL,'{\"kind\": \"judge\", \"value\": false}','由 $a=b$ 可得 $a^{2}=b^{2}$（充分），但由 $a^{2}=b^{2}$ 可能 $a=-b\\ne b$，故不必要，不是充要。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,34,12,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.689','2026-10-24 17:00:31.689'),(92,'HSMA-RJA-CH01-0067','formal','judge','“两个三角形全等”是“两个三角形面积相等”的充分不必要条件。',NULL,'{\"kind\": \"judge\", \"value\": true}','全等的三角形面积一定相等，故充分；面积相等未必全等，故不必要。结论成立。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,34,10,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.691','2026-10-24 17:00:31.691'),(93,'HSMA-RJA-CH01-0068','formal','numeric','在实数范围内，使命题“若 $x>a$，则 $x>3$”对一切实数 $x$ 恒成立。满足条件的实数 $a$ 的最小值是',NULL,'{\"kind\": \"numeric\", \"value\": \"3\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','“$x>a\\Rightarrow x>3$”对一切 $x$ 成立，当且仅当 $a\\ge 3$。若 $a<3$，取 $x$ 满足 $a<x\\le 3$，则前提真结论假。故最小值为 $3$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,34,10,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.694','2026-10-24 17:00:31.694'),(94,'HSMA-RJA-CH01-0069','formal','single','命题“$\\forall x\\in\\mathbb{R},\\,x^{2}\\ge 0$”是','{\"options\": [{\"id\": \"A\", \"text\": \"真命题\"}, {\"id\": \"B\", \"text\": \"假命题\"}, {\"id\": \"C\", \"text\": \"无法判断\"}, {\"id\": \"D\", \"text\": \"条件命题\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','任意实数的平方都大于或等于 $0$，因此该全称量词命题为真命题。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,35,13,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.698','2026-10-24 17:00:31.698'),(95,'HSMA-RJA-CH01-0070','formal','single','命题“$\\exists x\\in\\mathbb{R},\\,x^{2}+1=0$”是','{\"options\": [{\"id\": \"A\", \"text\": \"假命题\"}, {\"id\": \"B\", \"text\": \"真命题\"}, {\"id\": \"C\", \"text\": \"无法判断\"}, {\"id\": \"D\", \"text\": \"与量词无关\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','在实数集上 $x^{2}+1\\ge 1>0$，方程无实根，故存在量词命题为假。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,35,14,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.702','2026-10-24 17:00:31.702'),(96,'HSMA-RJA-CH01-0071','formal','single','命题“$\\forall x\\in\\mathbb{R},\\,x>0$”的否定是','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\exists x\\\\in\\\\mathbb{R},\\\\,x\\\\le 0$\"}, {\"id\": \"B\", \"text\": \"$\\\\forall x\\\\in\\\\mathbb{R},\\\\,x\\\\le 0$\"}, {\"id\": \"C\", \"text\": \"$\\\\exists x\\\\in\\\\mathbb{R},\\\\,x>0$\"}, {\"id\": \"D\", \"text\": \"$\\\\forall x\\\\in\\\\mathbb{R},\\\\,x<0$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','否定全称命题时，把 $\\forall$ 改为 $\\exists$，并把结论 $x>0$ 否定为 $x\\le 0$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,35,15,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.704','2026-10-24 17:00:31.704'),(97,'HSMA-RJA-CH01-0072','formal','single','命题“$\\exists x\\in\\mathbb{Z},\\,x^{2}=2$”的否定是','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\forall x\\\\in\\\\mathbb{Z},\\\\,x^{2}\\\\ne 2$\"}, {\"id\": \"B\", \"text\": \"$\\\\exists x\\\\in\\\\mathbb{Z},\\\\,x^{2}\\\\ne 2$\"}, {\"id\": \"C\", \"text\": \"$\\\\forall x\\\\in\\\\mathbb{Z},\\\\,x^{2}=2$\"}, {\"id\": \"D\", \"text\": \"$\\\\exists x\\\\in\\\\mathbb{R},\\\\,x^{2}=2$\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','否定存在命题时，把 $\\exists$ 改为 $\\forall$，并否定结论，得到任意整数都满足 $x^{2}\\ne 2$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,35,15,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.872','2026-10-24 17:00:31.872'),(98,'HSMA-RJA-CH01-0073','formal','single','下列为真命题的是','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\exists x\\\\in\\\\mathbb{R},\\\\,x^{2}-2x+1=0$\"}, {\"id\": \"B\", \"text\": \"$\\\\forall x\\\\in\\\\mathbb{R},\\\\,x^{2}-2x+1=0$\"}, {\"id\": \"C\", \"text\": \"$\\\\exists x\\\\in\\\\mathbb{R},\\\\,x^{2}+1=0$\"}, {\"id\": \"D\", \"text\": \"$\\\\forall x\\\\in\\\\mathbb{N},\\\\,x<0$（$\\\\mathbb{N}$ 含 $0$）\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','$x^{2}-2x+1=(x-1)^{2}=0$ 有实根 $x=1$，存在性为真。其余全称或存在命题均假。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,35,14,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.876','2026-10-24 17:00:31.876'),(99,'HSMA-RJA-CH01-0074','formal','single','命题“$\\forall x\\in\\{1,2,3\\},\\,x\\le 3$”是','{\"options\": [{\"id\": \"A\", \"text\": \"真命题\"}, {\"id\": \"B\", \"text\": \"假命题\"}, {\"id\": \"C\", \"text\": \"无法判断\"}, {\"id\": \"D\", \"text\": \"否定后仍真\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','论域只有 $1,2,3$，逐个检验均有 $x\\le 3$，故全称命题为真。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,35,13,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.879','2026-10-24 17:00:31.879'),(100,'HSMA-RJA-CH01-0075','formal','multi','下列命题为真的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$\\\\forall x\\\\in\\\\mathbb{R},\\\\,|x|\\\\ge 0$\"}, {\"id\": \"B\", \"text\": \"$\\\\exists x\\\\in\\\\mathbb{Z},\\\\,2x=5$\"}, {\"id\": \"C\", \"text\": \"$\\\\exists x\\\\in\\\\mathbb{R},\\\\,x^{2}<0$\"}, {\"id\": \"D\", \"text\": \"$\\\\exists n\\\\in\\\\mathbb{Z}^{+},\\\\,n^{2}=9$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"D\"]}','A 真。B：不存在整数使 $2x=5$。C：平方非负。D：取 $n=3$ 即可。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,35,13,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.883','2026-10-24 17:00:31.883'),(101,'HSMA-RJA-CH01-0076','formal','multi','关于命题否定，正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"“$\\\\forall x\\\\in M,\\\\,p(x)$”的否定是“$\\\\exists x\\\\in M,\\\\,\\\\neg p(x)$”\"}, {\"id\": \"B\", \"text\": \"“$\\\\exists x\\\\in M,\\\\,p(x)$”的否定是“$\\\\forall x\\\\in M,\\\\,\\\\neg p(x)$”\"}, {\"id\": \"C\", \"text\": \"否定时只需否定结论，量词不变\"}, {\"id\": \"D\", \"text\": \"否定全称命题时，全称与存在互换\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"D\"]}','含量词命题的否定规则是：全称与存在互换，并且否定结论。只改结论不改量词是错误的，故 C 不选。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,16,35,15,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.886','2026-10-24 17:00:31.886'),(102,'HSMA-RJA-CH01-0077','formal','judge','命题“$\\exists x\\in\\mathbb{R},\\,x^{2}=0$”是真命题。',NULL,'{\"kind\": \"judge\", \"value\": true}','取 $x=0$ 时 $x^{2}=0$ 成立，说明存在这样的实数，故命题为真。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,35,14,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.889','2026-10-24 17:00:31.889'),(103,'HSMA-RJA-CH01-0078','formal','judge','命题“$\\forall x\\in\\mathbb{R},\\,x^{2}>0$”是真命题。',NULL,'{\"kind\": \"judge\", \"value\": false}','取反例 $x=0$，此时 $x^{2}=0$ 并不大于 $0$，故全称命题为假。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,35,13,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.892','2026-10-24 17:00:31.892'),(104,'HSMA-RJA-CH01-0079','formal','numeric','在集合 $\\{1,2,3,4\\}$ 中，满足 $x>2$ 的元素个数是（可用于判断存在量词命题）',NULL,'{\"kind\": \"numeric\", \"value\": \"2\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','逐个检验：$3,4$ 满足 $x>2$，共 $2$ 个；因此“存在 $x$ 使 $x>2$”为真。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,16,35,14,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.894','2026-10-24 17:00:31.894'),(105,'HSMA-RJA-CH01-0080','formal','numeric','命题“$\\forall x\\in\\{2,4,6\\},\\,x$ 为偶数”为真。若从该集合中任取一个元素作为反例候选，可能推翻全称命题的反例个数是',NULL,'{\"kind\": \"numeric\", \"value\": \"0\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','$2,4,6$ 均为偶数，找不到使结论失败的元素，故可作反例的个数为 $0$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,16,35,13,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 17:00:31.897','2026-10-24 17:00:31.897'),(109,'HSMA-RJA-CH03-PARITY-0001','formal','single','设函数 $f$ 的定义域关于原点对称。若对定义域内任意 $x$ 都有 $f(-x)=f(x)$，则称 $f$ 为','{\"options\": [{\"id\": \"A\", \"text\": \"奇函数\"}, {\"id\": \"B\", \"text\": \"偶函数\"}, {\"id\": \"C\", \"text\": \"既奇又偶的函数\"}, {\"id\": \"D\", \"text\": \"非奇非偶函数\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','定义域关于原点对称是讨论奇偶性的前提。对任意 $x$ 有 $f(-x)=f(x)$ 时，$f$ 为偶函数。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,34,'approved',1,'v1',2,2,2,2,'2026-10-25 12:16:33.453','2026-10-24 20:15:07.568','2026-10-25 12:16:33.000'),(110,'HSMA-RJA-CH03-PARITY-0002','formal','judge','判断：若函数 $f$ 满足对定义域内任意 $x$ 都有 $f(-x)=-f(x)$，则 $f$ 一定是奇函数（无需再检查定义域）。',NULL,'{\"kind\": \"judge\", \"value\": false}','讨论奇偶性必须先检验定义域关于原点对称。仅有代数关系 $f(-x)=-f(x)$ 而定义域不对称时，不能称为奇函数。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,34,'approved',1,'v1',2,2,2,2,'2026-10-25 12:16:33.580','2026-10-24 20:15:07.575','2026-10-25 12:16:33.000'),(111,'HSMA-RJA-CH03-PARITY-0003','formal','single','下列关于函数奇偶性定义的叙述，正确的是','{\"options\": [{\"id\": \"A\", \"text\": \"只要 $f(-x)=-f(x)$ 成立，$f$ 就是奇函数\"}, {\"id\": \"B\", \"text\": \"偶函数必满足 $f(-x)=-f(x)$\"}, {\"id\": \"C\", \"text\": \"奇函数要求定义域关于原点对称，且 $f(-x)=-f(x)$\"}, {\"id\": \"D\", \"text\": \"奇偶性与定义域是否对称无关\"}]}','{\"kind\": \"single\", \"optionId\": \"C\"}','奇函数定义：定义域关于原点对称，且对定义域内任意 $x$ 有 $f(-x)=-f(x)$。缺一不可。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,34,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 20:15:07.579','2026-10-24 20:15:07.579'),(112,'HSMA-RJA-CH03-PARITY-0004','formal','multi','设函数 $f$ 定义域关于原点对称。下列说法正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"若 $f$ 为偶函数，则 $f(-x)=f(x)$\"}, {\"id\": \"B\", \"text\": \"若 $f$ 为奇函数，则 $f(-x)=-f(x)$\"}, {\"id\": \"C\", \"text\": \"若 $f(0)$ 有定义且 $f$ 为奇函数，则必有 $f(0)=0$\"}, {\"id\": \"D\", \"text\": \"若存在某 $a$ 使 $f(-a)\\\\neq f(a)$ 且 $f(-a)\\\\neq -f(a)$，则 $f$ 非奇非偶\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\", \"D\"]}','在定义域已对称的前提下：偶/奇分别对应 $f(-x)=f(x)$ / $f(-x)=-f(x)$。奇函数若 $0$ 在定义域，则 $f(0)=-f(0)\\Rightarrow f(0)=0$。若既不满足偶又不满足奇的恒等式，则为非奇非偶。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,18,42,34,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 20:15:07.583','2026-10-24 20:15:07.583'),(113,'HSMA-RJA-CH03-PARITY-0005','formal','single','已知 $f(x)=x^{3}$ 的定义域为 $\\mathbb{R}$。判断其奇偶性时，下列步骤正确的是','{\"options\": [{\"id\": \"A\", \"text\": \"直接看次数为奇数，故为奇函数，无需验证定义域\"}, {\"id\": \"B\", \"text\": \"先确认定义域关于原点对称，再验证 $f(-x)=-f(x)$\"}, {\"id\": \"C\", \"text\": \"只需验证 $f(-1)=-f(1)$ 即可断定为奇函数\"}, {\"id\": \"D\", \"text\": \"因为过原点，所以一定是偶函数\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','正确流程：先确认定义域对称（此处 $\\mathbb{R}$ 对称），再验证对任意 $x$，$f(-x)=(-x)^{3}=-x^{3}=-f(x)$，故为奇函数。仅验证个别点或只看次数不够严谨。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,35,'approved',1,'v1',2,2,2,2,'2026-10-25 12:16:33.699','2026-10-24 20:15:07.588','2026-10-25 12:16:33.000'),(114,'HSMA-RJA-CH03-PARITY-0006','formal','single','函数 $f(x)=\\sqrt{x-1}+\\sqrt{1-x}$ 的定义域','{\"options\": [{\"id\": \"A\", \"text\": \"关于原点对称，可讨论奇偶性\"}, {\"id\": \"B\", \"text\": \"为 $\\\\{1\\\\}$，关于原点不对称，故非奇非偶\"}, {\"id\": \"C\", \"text\": \"为 $[0,+\\\\infty)$，可讨论奇偶性\"}, {\"id\": \"D\", \"text\": \"为空集，规定为偶函数\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','由 $x-1\\ge 0$ 且 $1-x\\ge 0$ 得 $x=1$，定义域 $\\{1\\}$。关于原点的对称点 $-1\\notin\\{1\\}$，定义域不对称，故非奇非偶。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,34,'approved',1,'v1',2,2,2,2,'2026-10-25 12:16:33.820','2026-10-24 20:15:07.594','2026-10-25 12:16:33.000'),(115,'HSMA-RJA-CH03-PARITY-0007','formal','judge','判断：函数 $f(x)=\\dfrac{1}{x}$ 的定义域为 $(-\\infty,0)\\cup(0,+\\infty)$，关于原点对称，因此可以进一步用定义讨论其奇偶性。',NULL,'{\"kind\": \"judge\", \"value\": true}','定义域 $\\mathbb{R}\\setminus\\{0\\}$ 关于原点对称，具备讨论奇偶性的前提；再验证 $f(-x)=-1/x=-f(x)$ 可知其为奇函数。本题只考前提是否成立。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,34,'approved',1,'v1',2,2,2,2,'2026-10-25 12:16:33.920','2026-10-24 20:15:07.598','2026-10-25 12:16:33.000'),(116,'HSMA-RJA-CH03-PARITY-0008','formal','single','函数 $f(x)=\\sqrt{x^{2}-1}$ 的定义域为','{\"options\": [{\"id\": \"A\", \"text\": \"$[-1,1]$，关于原点对称\"}, {\"id\": \"B\", \"text\": \"$(-\\\\infty,-1]\\\\cup[1,+\\\\infty)$，关于原点对称\"}, {\"id\": \"C\", \"text\": \"$(1,+\\\\infty)$，关于原点不对称\"}, {\"id\": \"D\", \"text\": \"$[0,+\\\\infty)$，关于原点对称\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','由 $x^{2}-1\\ge 0$ 得 $x\\le -1$ 或 $x\\ge 1$，即 $(-\\infty,-1]\\cup[1,+\\infty)$。若 $x$ 属于该集合，则 $-x$ 也属于，故关于原点对称，可继续讨论奇偶性。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,18,42,35,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 20:15:07.601','2026-10-24 20:15:07.601'),(117,'HSMA-RJA-CH03-PARITY-0009','formal','multi','下列函数中，定义域关于原点对称的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$f(x)=\\\\sqrt{4-x^{2}}$\"}, {\"id\": \"B\", \"text\": \"$g(x)=\\\\ln(x+2)$\"}, {\"id\": \"C\", \"text\": \"$h(x)=\\\\dfrac{1}{x^{2}-1}$\"}, {\"id\": \"D\", \"text\": \"$p(x)=\\\\sqrt{x}+\\\\sqrt{-x}$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"C\", \"D\"]}','A：定义域 $[-2,2]$，对称。B：$x>-2$，不对称。C：$x\\neq\\pm 1$，仍关于原点对称。D：仅 $x=0$，对称。故选 A、C、D。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,18,42,35,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 20:15:07.605','2026-10-24 20:15:07.605'),(118,'HSMA-RJA-CH03-PARITY-0010','formal','single','函数 $f(x)=x^{2}+1$（定义域 $\\mathbb{R}$）是','{\"options\": [{\"id\": \"A\", \"text\": \"奇函数\"}, {\"id\": \"B\", \"text\": \"偶函数\"}, {\"id\": \"C\", \"text\": \"既奇又偶\"}, {\"id\": \"D\", \"text\": \"非奇非偶\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','定义域 $\\mathbb{R}$ 对称。$f(-x)=(-x)^{2}+1=x^{2}+1=f(x)$，故为偶函数。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,35,'approved',1,'v1',2,2,2,2,'2026-10-25 12:16:34.048','2026-10-24 20:15:07.609','2026-10-25 12:16:34.000'),(119,'HSMA-RJA-CH03-PARITY-0011','formal','single','函数 $f(x)=x^{3}-x$（定义域 $\\mathbb{R}$）是','{\"options\": [{\"id\": \"A\", \"text\": \"奇函数\"}, {\"id\": \"B\", \"text\": \"偶函数\"}, {\"id\": \"C\", \"text\": \"既奇又偶\"}, {\"id\": \"D\", \"text\": \"非奇非偶\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','定义域对称。$f(-x)=(-x)^{3}-(-x)=-x^{3}+x=-(x^{3}-x)=-f(x)$，故为奇函数。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,35,'approved',1,'v1',2,2,2,2,'2026-10-25 12:16:34.270','2026-10-24 20:15:07.613','2026-10-25 12:16:34.000'),(120,'HSMA-RJA-CH03-PARITY-0012','formal','multi','设 $f(x)=0$（定义域 $\\mathbb{R}$）。下列说法正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$f$ 是奇函数\"}, {\"id\": \"B\", \"text\": \"$f$ 是偶函数\"}, {\"id\": \"C\", \"text\": \"$f$ 既是奇函数又是偶函数\"}, {\"id\": \"D\", \"text\": \"$f$ 非奇非偶\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"B\", \"C\"]}','零函数在关于原点对称的定义域上：$f(-x)=0=f(x)$ 且 $f(-x)=0=-f(x)$，故既奇又偶。A、B、C 均正确，D 错误。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,18,42,36,'approved',1,'v1',2,2,2,2,'2026-10-25 12:16:34.549','2026-10-24 20:15:07.617','2026-10-25 12:16:34.000'),(121,'HSMA-RJA-CH03-PARITY-0013','formal','single','函数 $f(x)=x+|x|$（定义域 $\\mathbb{R}$）的奇偶性是','{\"options\": [{\"id\": \"A\", \"text\": \"奇函数\"}, {\"id\": \"B\", \"text\": \"偶函数\"}, {\"id\": \"C\", \"text\": \"既奇又偶\"}, {\"id\": \"D\", \"text\": \"非奇非偶\"}]}','{\"kind\": \"single\", \"optionId\": \"D\"}','定义域对称。$f(-x)=-x+|-x|=-x+|x|$。一般地 $f(-x)\\neq f(x)$（如 $x=1$：$f(1)=2$，$f(-1)=0$），且 $f(-x)\\neq -f(x)$（$-f(1)=-2\\neq 0$），故非奇非偶。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,18,42,36,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 20:15:07.622','2026-10-24 20:15:07.622'),(122,'HSMA-RJA-CH03-PARITY-0014','formal','judge','判断：函数 $f(x)=x^{2}+x$（定义域 $\\mathbb{R}$）是偶函数。',NULL,'{\"kind\": \"judge\", \"value\": false}','$f(-x)=x^{2}-x$。取 $x=1$，$f(-1)=0\\neq f(1)=2$，故不是偶函数；也不是奇函数（$f(-1)=0\\neq -2$），为非奇非偶。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,36,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 20:15:07.626','2026-10-24 20:15:07.626'),(123,'HSMA-RJA-CH03-PARITY-0015','formal','numeric','已知奇函数 $f$ 的定义域关于原点对称，且 $f(3)=5$。求 $f(-3)$ 的值。',NULL,'{\"kind\": \"numeric\", \"value\": \"-5\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','奇函数满足 $f(-x)=-f(x)$，故 $f(-3)=-f(3)=-5$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,37,'approved',1,'v1',2,2,2,2,'2026-10-25 12:16:34.709','2026-10-24 20:15:07.631','2026-10-25 12:16:34.000'),(124,'HSMA-RJA-CH03-PARITY-0016','formal','numeric','已知偶函数 $f$ 的定义域关于原点对称，且 $f(-2)=7$。求 $f(2)$ 的值。',NULL,'{\"kind\": \"numeric\", \"value\": \"7\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','偶函数满足 $f(-x)=f(x)$，故 $f(2)=f(-2)=7$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,37,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 20:15:07.635','2026-10-24 20:15:07.635'),(125,'HSMA-RJA-CH03-PARITY-0017','formal','numeric','已知奇函数 $f$ 定义在 $\\mathbb{R}$ 上，$f(1)=2$，$f(2)=5$。求 $f(-1)+f(-2)$ 的值。',NULL,'{\"kind\": \"numeric\", \"value\": \"-7\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','$f(-1)=-f(1)=-2$，$f(-2)=-f(2)=-5$，故和为 $-7$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,37,'draft',1,'v1',2,2,2,NULL,NULL,'2026-10-24 20:15:07.638','2026-10-24 22:00:56.000'),(126,'HSMA-RJA-CH03-PARITY-0018','formal','numeric','已知偶函数 $f$ 定义在 $\\mathbb{R}$ 上，$f(4)=3$，且 $f(x)=ax^{2}+b$（$a,b$ 为常数）。若还已知 $f(0)=1$，求 $f(-4)$ 的值。',NULL,'{\"kind\": \"numeric\", \"value\": \"3\", \"toleranceAbs\": 0, \"toleranceRel\": 0}','偶函数有 $f(-4)=f(4)=3$。由 $f(0)=1$ 可知常数项，但不影响 $f(\\pm 4)$ 的相等关系；本题所求仅为 $f(-4)$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,37,'draft',1,'v1',2,2,2,NULL,NULL,'2026-10-24 20:15:07.641','2026-10-24 22:00:56.000'),(127,'HSMA-RJA-CH03-PARITY-0019','formal','single','若函数 $y=f(x)$ 是偶函数，则其图象','{\"options\": [{\"id\": \"A\", \"text\": \"关于原点对称\"}, {\"id\": \"B\", \"text\": \"关于 $y$ 轴对称\"}, {\"id\": \"C\", \"text\": \"关于 $x$ 轴对称\"}, {\"id\": \"D\", \"text\": \"关于直线 $y=x$ 对称\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','由偶函数定义，$f(-x)=f(x)$，图象上点 $(x,y)$ 与 $(-x,y)$ 同时出现，故图象关于 $y$ 轴对称。奇函数则关于原点对称，二者不可混淆。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,36,'approved',1,'v1',2,2,2,2,'2026-10-25 12:16:34.809','2026-10-24 20:15:07.645','2026-10-25 12:16:34.000'),(128,'HSMA-RJA-CH03-PARITY-0020','formal','single','已知点 $(2,5)$ 在奇函数 $y=f(x)$ 的图象上，则下列点也在该图象上的是','{\"options\": [{\"id\": \"A\", \"text\": \"$(-2,5)$\"}, {\"id\": \"B\", \"text\": \"$(-2,-5)$\"}, {\"id\": \"C\", \"text\": \"$(2,-5)$\"}, {\"id\": \"D\", \"text\": \"$(5,2)$\"}]}','{\"kind\": \"single\", \"optionId\": \"B\"}','奇函数图象关于原点对称：点 $(a,b)$ 在图象上则 $(-a,-b)$ 也在图象上。故 $(2,5)$ 对应 $(-2,-5)$。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,36,'approved',1,'v1',3,2,2,2,'2026-10-25 12:16:34.900','2026-10-24 20:15:07.648','2026-10-25 12:16:34.000'),(129,'HSMA-RJA-CH03-PARITY-0021','formal','multi','已知偶函数 $y=f(x)$ 的图象过点 $(3,-1)$。下列说法正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"图象也过点 $(-3,-1)$\"}, {\"id\": \"B\", \"text\": \"图象也过点 $(-3,1)$\"}, {\"id\": \"C\", \"text\": \"图象关于 $y$ 轴对称\"}, {\"id\": \"D\", \"text\": \"必有 $f(-3)=f(3)$\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"C\", \"D\"]}','偶函数关于 $y$ 轴对称，故过 $(3,-1)$ 必过 $(-3,-1)$，且 $f(-3)=f(3)=-1$。B 的纵坐标符号错误。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,18,42,37,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 20:15:07.651','2026-10-24 20:15:07.651'),(130,'HSMA-RJA-CH03-PARITY-0022','formal','single','设 $f$ 是定义在 $\\mathbb{R}$ 上的奇函数，且 $f$ 在 $[0,+\\infty)$ 上单调递增。则 $f$ 在 $(-\\infty,0]$ 上','{\"options\": [{\"id\": \"A\", \"text\": \"单调递增\"}, {\"id\": \"B\", \"text\": \"单调递减\"}, {\"id\": \"C\", \"text\": \"先增后减\"}, {\"id\": \"D\", \"text\": \"无法判断\"}]}','{\"kind\": \"single\", \"optionId\": \"A\"}','取 $x_{1}<x_{2}\\le 0$，则 $0\\le -x_{2}<-x_{1}$。由正半轴递增得 $f(-x_{2})<f(-x_{1})$。又奇函数 $f(-x)=-f(x)$，故 $-f(x_{2})<-f(x_{1})$，即 $f(x_{1})<f(x_{2})$，从而在 $(-\\infty,0]$ 上也单调递增。必须明确所论区间与奇偶性。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,18,42,37,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 20:15:07.654','2026-10-24 20:15:07.654'),(131,'HSMA-RJA-CH03-PARITY-0023','formal','multi','设 $f$ 是定义在 $\\mathbb{R}$ 上的偶函数，且 $f$ 在 $[0,+\\infty)$ 上单调递减。下列正确的是（多选）','{\"options\": [{\"id\": \"A\", \"text\": \"$f$ 在 $(-\\\\infty,0]$ 上单调递增\"}, {\"id\": \"B\", \"text\": \"$f$ 在 $(-\\\\infty,0]$ 上单调递减\"}, {\"id\": \"C\", \"text\": \"对任意 $x$，有 $f(|x|)=f(x)$\"}, {\"id\": \"D\", \"text\": \"仅由偶函数不能推出其在正半轴单调\"}]}','{\"kind\": \"multi\", \"optionIds\": [\"A\", \"C\", \"D\"]}','偶函数关于 $y$ 轴对称：正半轴递减对应负半轴递增（可类似用对称点证明）。$f(|x|)=f(x)$ 对偶函数成立。偶函数本身不蕴含单调性，D 正确。B 错误。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',3,18,42,37,'draft',1,'v1',1,2,2,NULL,NULL,'2026-10-24 20:15:07.659','2026-10-24 20:15:07.659'),(132,'HSMA-RJA-CH03-PARITY-0024','formal','judge','判断：任意奇函数在其整个定义域上都一定是单调函数。',NULL,'{\"kind\": \"judge\", \"value\": false}','反例：$f(x)=x^{3}-x$ 是奇函数，但在 $\\mathbb{R}$ 上不单调（局部有增减）。奇偶性与单调性相互独立，综合题必须另行给出单调区间条件。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',2,18,42,35,'draft',1,'v1',2,2,2,NULL,NULL,'2026-10-24 20:15:07.662','2026-10-24 22:00:57.000'),(133,'HSMA-RJA-CH03-PARITY-0025','formal','single','设 $f$ 是定义在 $[-2,2]$ 上的偶函数，且当 $x\\in[0,2]$ 时 $f(x)=x+1$。则 $f(-1)$ 等于','{\"options\": [{\"id\": \"A\", \"text\": \"$0$\"}, {\"id\": \"B\", \"text\": \"$1$\"}, {\"id\": \"C\", \"text\": \"$2$\"}, {\"id\": \"D\", \"text\": \"$-1$\"}]}','{\"kind\": \"single\", \"optionId\": \"C\"}','偶函数有 $f(-1)=f(1)$。又 $1\\in[0,2]$，故 $f(1)=1+1=2$，从而 $f(-1)=2$。定义域 $[-2,2]$ 关于原点对称，条件充分。','original',NULL,NULL,NULL,NULL,NULL,'unverified','unknown',1,18,42,35,'approved',1,'v1',3,2,2,2,'2026-10-25 12:16:34.999','2026-10-24 20:15:07.666','2026-10-25 12:16:35.000'),(151,'HSMA-RJA-CH03-APP-0001','formal','application','某社区游泳馆暑假期间调整日票价格。\n调查表明：当票价定为 $x$ 元（$x$ 为正整数，且 $30\\le x\\le 60$）时，预计日接待人数为 $2400-30x$ 人。\n设该馆日票务收入为 $y$ 元。\n\n（1）写出 $y$ 关于 $x$ 的函数解析式，并写出定义域；\n（2）求使日票务收入最大的票价，以及相应的最大日票务收入。\n\n（要求写出必要的建模与求解过程。）',NULL,'{\"kind\": \"application\", \"rubric\": [{\"key\": \"model\", \"title\": \"建立收入函数模型\", \"criteria\": \"写出 y=x(2400-30x) 或 2400x-30x²。仅列式缺说明可扣 1；模型结构错误本项 0～1。\", \"maxScore\": 3}, {\"key\": \"domain\", \"title\": \"定义域与实际约束\", \"criteria\": \"给出 30≤x≤60 的整数定义域（或等价表述）。仅写区间未提整数可给 1。\", \"maxScore\": 2}, {\"key\": \"solve\", \"title\": \"最值推导过程\", \"criteria\": \"用配方/顶点/单调性正确求得 x=40。方法对计算错可给 1～2；无过程猜答案 0～1。\", \"maxScore\": 3}, {\"key\": \"conclusion\", \"title\": \"实际结论与单位\", \"criteria\": \"明确票价 40 元、最大收入 48000 元。缺单位或结论孤立给 1；答案错 0。\", \"maxScore\": 2}], \"maxScore\": 10, \"standardAnswer\": \"（1）$y=x(2400-30x)=2400x-30x^{2}$，定义域 $x\\\\in\\\\{30,31,\\\\ldots,60\\\\}$。\\n（2）当 $x=40$ 元时日票务收入最大，最大日收入为 $48000$ 元。\"}','收入等于票价乘以人数：\n$y=x(2400-30x)$。\n整理得 $y=2400x-30x^{2}$。\n因为票价为正整数且 $30\\le x\\le 60$，所以定义域为 $\\{30,31,\\ldots,60\\}$。\n配方：$y=-30(x-40)^{2}+48000$。\n因为 $-30(x-40)^{2}\\le 0$，且 $x=40$ 属于定义域，所以 $x=40$ 时收入最大。\n最大收入为 $48000$ 元。','original',NULL,NULL,NULL,'原创设计建议：人教A版必修第三章「函数的应用（一）」情境下的票价—人数—收入建模题；尚未人工核实是否与公开题雷同。',NULL,'unverified','unknown',2,18,44,31,'approved',1,'v1',3,2,2,2,'2026-10-25 14:01:36.684','2026-10-25 13:49:09.540','2026-10-25 14:01:36.000');
